<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigRefreshTokenTtlSecondsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigRefreshTokenTtlSecondsAccessor trait.
 *
 * Covers null default, string/VO assignment via withRefreshTokenTtlSeconds,
 * getRefreshTokenTtlSeconds/refreshTokenTtlSeconds accessors, and isRefreshTokenTtlSecondsChanged with/without original.
 */
class TenantConfigRefreshTokenTtlSecondsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRefreshTokenTtlSeconds creates a new instance with the RefreshTokenTtlSeconds set
     * from a string value, and getRefreshTokenTtlSeconds returns the primitive string.
     */
    public function testWithRefreshTokenTtlSecondsFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRefreshTokenTtlSecondsAccessorUnitTest();

        // Act
        $result = $holder->withRefreshTokenTtlSeconds(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getRefreshTokenTtlSeconds());
    }
    /**
     * Asserts that withrefreshTokenTtlSeconds has access to the value object
     * from a string value, and getRefreshTokenTtlSeconds returns the primitive string.
     */
    public function testWithRefreshTokenTtlSecondsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRefreshTokenTtlSecondsAccessorUnitTest();

        // Act
        $result = $holder->withRefreshTokenTtlSeconds(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->refreshTokenTtlSeconds()->value());
    }
    public function testChangedRefreshTokenTtlSeconds(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRefreshTokenTtlSecondsAccessorUnitTest()->withRefreshTokenTtlSeconds(1);
        $original = $holder->withRefreshTokenTtlSeconds(1);
        $same = $holder->withRefreshTokenTtlSeconds(1);
        $modified = $holder->withRefreshTokenTtlSeconds(2);

        // Act
        $withSame = $original->isRefreshTokenTtlSecondsChanged($same);
        $withDiferent = $original->isRefreshTokenTtlSecondsChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigRefreshTokenTtlSecondsAccessorUnitTest
{
    use TenantConfigRefreshTokenTtlSecondsAccessor;
}
